function solve(input) {
  const { tree } = input;
  if (!tree || tree.length === 0 || tree[0] === null) return [];
  const res = [];
  function dfs(idx, level) {
    if (idx >= tree.length || tree[idx] === null || tree[idx] === undefined) return;
    if (!res[level]) res[level] = [];
    res[level].push(tree[idx]);
    dfs(2 * idx + 1, level + 1);
    dfs(2 * idx + 2, level + 1);
  }
  dfs(0, 0);
  return res;
}
